// Before normalization (function): get_day_bonus.
static long getDayBonus(int resource, long weekBonus, long day)
{
    long result = weekBonus / 7;
    long remainder = weekBonus % 7;
    if ((day - resource + 6) % 7 < remainder)
        ++result;
    return result;
}

