void game::setCannedRumour()
{
    int available = 0;
    int i;
    for (i = 0; i < 256; i++) {
        if (!m_rumourState[i])
            available++;
    }

    if (!available) {
        memset(m_rumourState, 0, sizeof(m_rumourState));
        available = 256;
    }

    int selected = random(1, available);
    int seen = 0;
    for (i = 0; i < 256; i++) {
        if (!m_rumourState[i])
            seen++;
        if (seen == selected) {
            m_rumourState[i] = 1;
            strcpy(m_currentRumour, g_cannedRumours[selected]);
            return;
        }
    }
}

