{
#pragma inline_depth(0)
    _Tidy(0);
#pragma inline_depth()
    return *this;
}

template<> std::bitset<70>& std::bitset<70>::reset()
{
#pragma inline_depth(0)
    _Tidy(0);
#pragma inline_depth()
    return *this;
}

template<> std::bitset<128>& std::bitset<128>::reset()
{
#pragma inline_depth(0)
    _Tidy(0);
#pragma inline_depth()
    return *this;
}

